import { test, expect } from '@playwright/test';

test.describe('Email Registration - Unique Email Requirement', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/register');
  });

  test('should display error when registering with an already-used email', async ({ page }) => {
    // Setup: Fill in valid form data
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('user@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('SecurePassword123');

    const confirmPasswordInput = page.getByLabel('Confirm Password');
    await confirmPasswordInput.fill('SecurePassword123');

    const submitButton = page.getByRole('button', { name: /register/i });
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText('Email already in use');
    await expect(errorMessage).toBeVisible();

    // Verify form is still visible
    const form = page.locator('[data-testid="registration-form"]');
    await expect(form).toBeVisible();

    // Verify error message is displayed
    const errorList = page.locator('[data-testid="error-list"]');
    await expect(errorList).toBeVisible();

    // Verify error message contains specific text
    await expect(errorMessage).toContainText('Email already in use');

    // Verify error message has a clear action button
    const clearButton = page.getByRole('button', { name: /clear/i });
    await expect(clearButton).toBeVisible();

    // Verify error message has a dismiss button
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify error message has a close icon
    const closeIcon = page.getByRole('button', { name: /close/i });
    await expect(closeIcon).toBeVisible();

    // Verify error message has a styling class
    const errorClass = page.getByTestId('error-message');
    await expect(errorClass).toHaveClass(/error/i);
  });

  test('should not display error when registering with a new email', async ({ page }) => {
    // Setup: Fill in valid form data with a new email
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('newuser@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('SecurePassword123');

    const confirmPasswordInput = page.getByLabel('Confirm Password');
    await confirmPasswordInput.fill('SecurePassword123');

    const submitButton = page.getByRole('button', { name: /register/i });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Registration successful');
    await expect(successMessage).toBeVisible();

    // Verify form is still visible
    const form = page.locator('[data-testid="registration-form"]');
    await expect(form).toBeVisible();

    // Verify success message is displayed
    const successList = page.locator('[data-testid="success-list"]');
    await expect(successList).toBeVisible();

    // Verify success message contains specific text
    await expect(successMessage).toContainText('Registration successful');

    // Verify error message is not visible
    const errorMessage = page.getByText('Email already in use');
    await expect(errorMessage).not.toBeVisible();

    // Verify error message has no styling class
    const errorClass = page.getByTestId('error-message');
    await expect(errorClass).not.toHaveClass(/error/i);

    // Verify error message is not present
    const errorList = page.locator('[data-testid="error-list"]');
    await expect(errorList).not.toBeVisible();
  });
});
